const searchProjectsSummary = `-- name: SearchProjectsSummary :one
WITH hits AS (
    SELECT p.id,
           CASE WHEN lower(p.title) = lower($1::text) THEN 0
                WHEN starts_with(lower(p.title), lower($1::text)) THEN 1
                ELSE 2 END AS rank
    FROM projects p
    WHERE NOT $2::boolean AND p.title ILIKE $3::text
    UNION ALL
    SELECT p.id, 3 FROM projects p WHERE $2::boolean AND p.title %> $1::text
    UNION ALL
    SELECT ps.project_id, 4
    FROM skills s
    JOIN project_skills ps ON ps.skill_id = s.id
    WHERE s.name::text ILIKE $3::text
    UNION ALL
    SELECT p.id, 5 FROM projects p WHERE p.description ILIKE $3::text
), best AS (
    SELECT id, min(rank) AS rank FROM hits GROUP BY id
), matches AS (
    SELECT b.id, b.rank, p.title
    FROM best b
    JOIN projects p ON p.id = b.id
    JOIN project_members o ON o.project_id = p.id AND o.role = 'owner'
    JOIN users u ON u.id = o.user_id
    WHERE p.status = 'open' AND u.email_verified_at IS NOT NULL AND u.suspended_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM blocks x WHERE x.blocker_id = o.user_id AND x.blocked_id = $4::uuid)
)
SELECT count(*)::int AS total,
       coalesce((array_agg(m.title ORDER BY word_similarity($1::text, m.title) DESC, similarity(m.title, $1::text) DESC, m.title, m.id)
                 FILTER (WHERE m.rank = 3))[1], '')::text AS corrected_query
FROM matches m
`

type SearchProjectsSummaryParams struct {
	Q        string
	Fuzzy    bool
	Pattern  string
	ViewerID pgtype.UUID
}

type SearchProjectsSummaryRow struct {
	Total          int32
	CorrectedQuery string
}

// The number of results, and the title most similar to q among the similar-title results
// (” when there are none).
func (q *Queries) SearchProjectsSummary(ctx context.Context, arg SearchProjectsSummaryParams) (SearchProjectsSummaryRow, error) {
	row := q.db.QueryRow(ctx, searchProjectsSummary,
		arg.Q,
		arg.Fuzzy,
		arg.Pattern,
		arg.ViewerID,
	)
	var i SearchProjectsSummaryRow
	err := row.Scan(&i.Total, &i.CorrectedQuery)
	return i, err
}

const semanticProjectCandidates = `-- name: SemanticProjectCandidates :many
WITH cand AS MATERIALIZED (
    SELECT e.project_id, (e.embedding <=> CAST($2::text AS vector))::float8 AS distance
    FROM project_embeddings e
    JOIN projects p ON p.id = e.project_id
    JOIN project_members o ON o.project_id = p.id AND o.role = 'owner'
    JOIN users u ON u.id = o.user_id
    WHERE e.model = $3::text
      AND p.status = 'open' AND u.email_verified_at IS NOT NULL AND u.suspended_at IS NULL
      AND NOT EXISTS (SELECT 1 FROM blocks x WHERE x.blocker_id = o.user_id AND x.blocked_id = $1::uuid)
    ORDER BY e.embedding <=> CAST($2::text AS vector)
    LIMIT $4
)
SELECT p.id, p.title, left(p.description, 300)::text AS description, p.status::text AS status,
       p.created_at, p.updated_at,
       coalesce((SELECT m.role::text FROM project_members m WHERE m.project_id = p.id AND m.user_id = $1::uuid), '')::text AS my_role,
       o.user_id AS owner_id,
       coalesce(op.full_name, '')::text AS owner_name, op.headline AS owner_headline, op.photo_file_id AS owner_photo
FROM cand
JOIN projects p ON p.id = cand.project_id
JOIN project_members o ON o.project_id = p.id AND o.role = 'owner'
LEFT JOIN profiles op ON op.user_id = o.user_id
ORDER BY cand.distance, cand.project_id
`

type SemanticProjectCandidatesParams struct {
	ViewerID  pgtype.UUID
	Embedding string
	Model     string
	Lim       int32
}

type SemanticProjectCandidatesRow struct {
	ID            pgtype.UUID
	Title         string
	Description   string
	Status        string
	CreatedAt     pgtype.Timestamptz
	UpdatedAt     pgtype.Timestamptz
	MyRole        string
	OwnerID       pgtype.UUID
	OwnerName     string
	OwnerHeadline pgtype.Text
	OwnerPhoto    pgtype.UUID
}

// The lim visible open projects whose embedding is closest in cosine distance to the query
// vector, through project_embeddings_hnsw_idx, among embeddings of the query's model. The
// order is the cosine distance and nothing else, then the ID for ties.
func (q *Queries) SemanticProjectCandidates(ctx context.Context, arg SemanticProjectCandidatesParams) ([]SemanticProjectCandidatesRow, error) {
	rows, err := q.db.Query(ctx, semanticProjectCandidates,
		arg.ViewerID,
		arg.Embedding,
		arg.Model,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SemanticProjectCandidatesRow
	for rows.Next() {
		var i SemanticProjectCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Description,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MyRole,
			&i.OwnerID,
			&i.OwnerName,
			&i.OwnerHeadline,
			&i.OwnerPhoto,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

